def audit(slug, action, target, summary, workq_item_id=None):
    if not slug:
        return
    today = datetime.datetime.utcnow().strftime("%Y-%m-%d")
    path = "PracticeManager/AuditLog/" + slug + "-" + today + ".jsonl"
    try:
        existing = api.files.read(file=path)
    except Exception:
        existing = ""
    entry = {
        "ts": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
        "practice_slug": slug,
        "actor": "agent",
        "source": "automation:New enquiry handling",
        "action": action,
        "target": target,
        "summary": summary,
    }
    if workq_item_id:
        entry["workq_item_id"] = workq_item_id
    line = json.dumps(entry, sort_keys=True)
    api.files.put(file=path, content=(existing + line + "\n") if existing else (line + "\n"))


responses = params.get("responses") or {}
todo_id = params.get("todo_id") or ""
outcome = "ignored"

if responses and todo_id:
    draft = read_json("PracticeManager/BookingDrafts/" + todo_id + ".json", None)
    if not draft:
        outcome = "ignored"
    else:
        decision = str(responses.get("q_decision") or "")
        thread_todo_id = draft.get("thread_todo_id") or ""
        slug = draft.get("slug") or ""
        enquirer_email = draft.get("enquirer_email") or ""
        first_name = draft.get("first_name") or "the patient"

        def update_thread(patch):
            if not thread_todo_id:
                return
            thread = read_json("PracticeManager/EnquiryThreads/" + thread_todo_id + ".json", {}) or {}
            thread.update(patch)
            write_json("PracticeManager/EnquiryThreads/" + thread_todo_id + ".json", thread)

        if decision == "Don't send":
            api.workq.comment(todo_id=todo_id, body="Marked as don't book. No patient was created and nothing was sent.")
            api.workq.complete(todo_id=todo_id)
            update_thread({"status": "not_booked"})
            audit(slug, "rejected", {"kind": "booking", "id": todo_id}, "Reviewer declined to book " + first_name, todo_id)
            outcome = "not_booked"
        else:
            business_id = draft.get("business_id") or ""
            practitioner_id = draft.get("practitioner_id") or ""
            appointment_type_id = draft.get("appointment_type_id") or ""
            starts_at = draft.get("starts_at") or ""

            if not (business_id and practitioner_id and appointment_type_id and starts_at):
                api.workq.comment(todo_id=todo_id, body="This booking is missing required details and couldn't be created automatically. Book it manually in Cliniko.")
                outcome = "missing_details"
            else:
                # Re-check availability immediately before booking - times can fill between the offer and approval.
                still_free = False
                try:
                    day = datetime.datetime.strptime(starts_at[:10], "%Y-%m-%d")
                    avail = api.connectors.invoke(
                        server="cliniko-scheduling", tool="get_available_times",
                        args={
                            "business_id": business_id, "practitioner_id": practitioner_id,
                            "appointment_type_id": appointment_type_id,
                            "from_time": starts_at[:10],
                            "to_time": (day + datetime.timedelta(days=6)).strftime("%Y-%m-%d"),
                        },
                    )
                    raw_slots = avail if isinstance(avail, list) else (avail or {}).get("available_times") or []
                    offered_times = {str((s.get("appointment_start") if isinstance(s, dict) else s) or "") for s in raw_slots}
                    still_free = starts_at in offered_times
                except Exception:
                    still_free = False

                if not still_free:
                    new_slot = None
                    try:
                        today_str = datetime.datetime.utcnow().strftime("%Y-%m-%d")
                        to_str = (datetime.datetime.utcnow() + datetime.timedelta(days=6)).strftime("%Y-%m-%d")
                        avail = api.connectors.invoke(
                            server="cliniko-scheduling", tool="get_available_times",
                            args={
                                "business_id": business_id, "practitioner_id": practitioner_id,
                                "appointment_type_id": appointment_type_id,
                                "from_time": today_str, "to_time": to_str,
                            },
                        )
                        raw_slots = avail if isinstance(avail, list) else (avail or {}).get("available_times") or []
                        for s in raw_slots:
                            t = s.get("appointment_start") if isinstance(s, dict) else s
                            if t:
                                new_slot = str(t)
                                break
                    except Exception:
                        new_slot = None

                    if enquirer_email:
                        body = (
                            "Hi " + first_name + ", sorry - that time's just been taken. "
                            + ("The next time we have free is " + new_slot + ". Does that work?" if new_slot else
                               "Could you let us know another time that suits, or call us to find one?")
                        )
                        try:
                            api.connectors.invoke(
                                server="m365-mail-send", tool="send_email",
                                args={"to": [enquirer_email], "subject": "That time's just gone - here's another option", "body": body, "contentType": "Text"},
                            )
                        except Exception:
                            pass
                    api.workq.comment(todo_id=todo_id, body="The offered time was taken before approval. Sent " + first_name + " a re-offer instead of booking.")
                    api.workq.complete(todo_id=todo_id)
                    update_thread({
                        "status": "re_offered",
                        "proposed_appointment": ({"appointment_type_id": appointment_type_id, "business_id": business_id, "practitioner_id": practitioner_id, "starts_at": new_slot} if new_slot else None),
                    })
                    audit(slug, "sent", {"kind": "email", "id": enquirer_email}, "Re-offered a new time after the original slot was taken", todo_id)
                    outcome = "re_offered"
                else:
                    patient_id = ""
                    try:
                        existing = api.connectors.invoke(server="cliniko-patients", tool="list_patients", args={"q": ["email:=" + enquirer_email]})
                        rows = existing if isinstance(existing, list) else (existing or {}).get("patients") or []
                        if rows:
                            patient_id = str(rows[0].get("id") or "")
                    except Exception:
                        patient_id = ""

                    if not patient_id:
                        patient_payload = {"first_name": first_name, "last_name": draft.get("last_name") or "", "email": enquirer_email}
                        if draft.get("dob"):
                            patient_payload["date_of_birth"] = draft["dob"]
                        try:
                            patient = api.connectors.invoke(server="cliniko-patients", tool="create_patient", args={"patient": patient_payload})
                            patient_id = str((patient or {}).get("id") or "")
                        except Exception:
                            patient_id = ""

                    if not patient_id:
                        api.workq.comment(todo_id=todo_id, body="Couldn't create or find the patient record in Cliniko. Nothing was booked.")
                        outcome = "patient_create_failed"
                    else:
                        try:
                            appt = api.connectors.invoke(
                                server="cliniko-scheduling", tool="create_individual_appointment",
                                args={"appointment": {
                                    "appointment_type_id": appointment_type_id, "business_id": business_id,
                                    "practitioner_id": practitioner_id, "patient_id": patient_id, "starts_at": starts_at,
                                }},
                            )
                            appointment_id = str((appt or {}).get("id") or "")
                        except Exception:
                            appointment_id = ""

                        if not appointment_id:
                            api.workq.comment(todo_id=todo_id, body="Created the patient (" + patient_id + ") but the booking itself failed. Book the appointment manually in Cliniko.")
                            outcome = "appointment_create_failed"
                        else:
                            patient_form_id = ""
                            template_id = draft.get("intake_form_template_id") or ""
                            if template_id:
                                try:
                                    pf = api.connectors.invoke(
                                        server="cliniko-clinical", tool="create_patient_form",
                                        args={"patient_form": {"patient_id": patient_id, "form_template_id": template_id}},
                                    )
                                    patient_form_id = str((pf or {}).get("id") or "")
                                except Exception:
                                    patient_form_id = ""

                            form_url = ""
                            if patient_form_id:
                                try:
                                    pf_detail = api.connectors.invoke(server="cliniko-clinical", tool="get_patient_form", args={"id": patient_form_id})
                                    form_url = str((pf_detail or {}).get("url") or "")
                                except Exception:
                                    form_url = ""

                            if enquirer_email:
                                edited = str(responses.get("q_edited_message") or "").strip()
                                default_body = (
                                    "Hi " + first_name + ", you're all booked in for " + starts_at + " (Australian Eastern time). "
                                    + ("Please complete your intake form before your visit: " + form_url + " " if form_url else "")
                                    + "See you soon!"
                                )
                                body = edited if (decision == "Edit and send" and edited) else default_body
                                try:
                                    api.connectors.invoke(
                                        server="m365-mail-send", tool="send_email",
                                        args={"to": [enquirer_email], "subject": "You're booked in", "body": body, "contentType": "Text"},
                                    )
                                except Exception:
                                    pass

                            update_thread({
                                "status": "booked",
                                "patient_id": patient_id,
                                "appointment_id": appointment_id,
                                "patient_form_id": patient_form_id,
                                "appointment_starts_at": starts_at,
                                "form_complete": False,
                                "form_chased": False,
                            })
                            api.workq.comment(todo_id=todo_id, body="Booked " + first_name + " for " + starts_at + (" and sent the intake form." if patient_form_id else "."))
                            api.workq.complete(todo_id=todo_id)
                            audit(slug, "sent", {"kind": "appointment", "id": appointment_id}, "Booked " + first_name + " for " + starts_at, todo_id)
                            outcome = "booked"

