seen = read_json("PracticeManager/EnquirySeen/seen.json", default=[])
if not isinstance(seen, list):
    seen = []
seen_set = set(seen)

try:
    emails = api.connectors.invoke(server="m365-mail-read", tool="list_emails", args={"folder": "Inbox", "limit": 25, "unreadOnly": True})
except Exception:
    emails = []
if not isinstance(emails, list):
    emails = []

candidates = []
for e in emails:
    if not isinstance(e, dict):
        continue
    email_id = e.get("id") or ""
    if not email_id or email_id in seen_set:
        continue
    sender = e.get("from") or {}
    addr_block = sender.get("emailAddress") or {}
    from_email = str(addr_block.get("address") or "").lower()
    from_name = str(addr_block.get("name") or from_email)
    if not from_email or from_email.endswith("@mysmb.com"):
        # Our own outbound mail landing back in the inbox (CC, auto-reply) - never a patient enquiry.
        seen_set.add(email_id)
        continue

    # Skip existing patients - this automation is for NEW enquiries only (step 2 of the spec).
    try:
        existing = api.connectors.invoke(server="cliniko-patients", tool="list_patients", args={"q": ["email:=" + from_email]})
        rows = existing if isinstance(existing, list) else (existing or {}).get("patients") or []
    except Exception:
        rows = []
    if rows:
        seen_set.add(email_id)
        continue

    candidates.append({
        "email_id": email_id,
        "subject": e.get("subject") or "",
        "from_name": from_name,
        "from_email": from_email,
    })

write_json("PracticeManager/EnquirySeen/seen.json", sorted(seen_set))
