import json
import datetime

AI_TRIAGE_PROMPT = (
    "You are triaging an inbox email for a healthcare clinic to decide whether it is a genuine "
    "new-patient enquiry (someone asking about booking an appointment, services or fees, and not "
    "already a patient) rather than spam, a newsletter, or something only a human can judge. If "
    "you are not confident it's a genuine new-patient enquiry, say so rather than guessing. If a "
    "list of practices is given, say which one (by slug) the email is most likely about; if you "
    "can't tell, leave it blank. Never invent details that aren't in the email."
)
AI_TRIAGE_HINT = json.dumps({
    "is_new_enquiry": True,
    "confident": True,
    "practice_slug": "",
    "enquirer_first_name": "",
    "enquirer_last_name": "",
    "reason_for_visit": "",
})
AI_REPLY_PROMPT = (
    "Write a warm, concise reply to a new-patient enquiry for a healthcare clinic, in the tone "
    "given, using only the services and appointment times supplied. Never invent a price, service "
    "or time that wasn't provided, and never give clinical advice, diagnosis or interpretation. "
    "Use Australian English and Australian date/time conventions (e.g. 14 Nov, 9:00am)."
)
AI_REPLY_HINT = json.dumps({"subject": "", "body": ""})


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True))


def mark_seen(email_id):
    seen = read_json("PracticeManager/EnquirySeen/seen.json", default=[])
    if not isinstance(seen, list):
        seen = []
    seen_set = set(seen)
    seen_set.add(email_id)
    write_json("PracticeManager/EnquirySeen/seen.json", sorted(seen_set))


