item = params.get("item") or {}
email_id = item.get("email_id") or ""
outcome = "skipped"

if email_id:
    try:
        full = api.connectors.invoke(server="m365-mail-read", tool="get_email", args={"id": email_id})
    except Exception:
        full = None
    full = full if isinstance(full, dict) else {}
    body_block = full.get("body") or {}
    body_content = body_block.get("content") if isinstance(body_block, dict) else str(body_block or "")

    practices = []
    try:
        entries = api.files.list(path="PracticeManager/Practices", scope="org")
    except Exception:
        entries = []
    for entry in entries or []:
        fname = entry.get("name") if isinstance(entry, dict) else entry
        if not fname or not str(fname).endswith(".json"):
            continue
        slug = str(fname)[:-5]
        practice = read_json("PracticeManager/Practices/" + fname, {}) or {}
        if practice:
            practices.append({"slug": slug, "practice": practice})

    try:
        triage = api.ai.extract(
            prompt=AI_TRIAGE_PROMPT,
            input=json.dumps({
                "subject": item.get("subject") or "",
                "from_name": item.get("from_name") or "",
                "from_email": item.get("from_email") or "",
                "body": body_content or "",
                "practices": [{"slug": p["slug"], "name": p["practice"].get("name")} for p in practices],
            }),
            schema_hint=AI_TRIAGE_HINT,
        )
    except Exception:
        triage = {}
    triage = triage if isinstance(triage, dict) else {}

    if not triage.get("is_new_enquiry") or not triage.get("confident", True):
        if triage.get("is_new_enquiry") and not triage.get("confident", True):
            # Ambiguous rather than clearly not-an-enquiry: surface it instead of silently skipping.
            api.workq.create(
                title="New enquiry - needs a human look",
                scope="org",
                description=(
                    "This looks like it might be a new-patient enquiry but the triage wasn't confident enough "
                    "to draft a reply automatically.\n\n**From:** " + (item.get("from_name") or item.get("from_email") or "")
                    + " (" + (item.get("from_email") or "") + ")\n\n**Subject:** " + (item.get("subject") or "")
                    + "\n\n" + (body_content or "")[:2000]
                ),
                priority="normal",
                assignee_ids=None,
                labels=["healthcare-practice-management", "new-enquiry", "needs-triage"],
            )
        mark_seen(email_id)
        outcome = "not_an_enquiry"
    else:
        match_slug = str(triage.get("practice_slug") or "").strip()
        matched = next((p for p in practices if p["slug"] == match_slug), None)
        if not matched and len(practices) == 1:
            matched = practices[0]

        if not matched:
            api.workq.create(
                title="New enquiry - couldn't tell which practice",
                scope="org",
                description=(
                    "An enquiry arrived from **" + (item.get("from_name") or item.get("from_email") or "") + "** "
                    "(" + (item.get("from_email") or "") + ") but it couldn't be matched to a configured practice. "
                    "Triage it manually.\n\n**Subject:** " + (item.get("subject") or "") + "\n\n" + (body_content or "")[:2000]
                ),
                priority="normal",
                assignee_ids=None,
                labels=["healthcare-practice-management", "new-enquiry", "needs-triage"],
            )
            mark_seen(email_id)
            outcome = "unmatched_practice"
        else:
            slug = matched["slug"]
            practice = matched["practice"]
            business_id = str(practice.get("cliniko_business_id") or "")
            appt_type_name = str(practice.get("new_patient_appointment_type") or "").strip()
            policy = practice.get("policy") or {}
            tone = policy.get("tone") or "warm, concise, no jargon"
            reviewer = practice.get("reviewer_id") or ""

            services = []
            try:
                billable = api.connectors.invoke(server="cliniko-billing", tool="list_billable_items", args={"per_page": 100})
                rows = billable if isinstance(billable, list) else (billable or {}).get("billable_items") or []
                for row in rows:
                    if not isinstance(row, dict):
                        continue
                    if row.get("item_type") and row.get("item_type") != "Service":
                        continue
                    name = row.get("name")
                    price = row.get("price")
                    if name:
                        services.append({"name": name, "price": price})
            except Exception:
                services = []

            proposed_appointment = None
            appointment_type_id = ""
            practitioner_id = ""
            slot_options = []
            if business_id and appt_type_name:
                try:
                    types_result = api.connectors.invoke(server="cliniko-scheduling", tool="list_appointment_types", args={"per_page": 100})
                    type_rows = types_result if isinstance(types_result, list) else (types_result or {}).get("appointment_types") or []
                    appt_type = next(
                        (t for t in type_rows if isinstance(t, dict) and str(t.get("name") or "").strip().lower() == appt_type_name.lower()),
                        None,
                    )
                    appointment_type_id = str((appt_type or {}).get("id") or "")
                except Exception:
                    appointment_type_id = ""

                if appointment_type_id:
                    try:
                        prac_result = api.connectors.invoke(server="cliniko-practice", tool="list_practitioners", args={"business_id": business_id})
                        practitioners = prac_result if isinstance(prac_result, list) else (prac_result or {}).get("practitioners") or []
                        practitioner_id = str((practitioners[0] or {}).get("id") or "") if practitioners else ""
                    except Exception:
                        practitioner_id = ""

                if appointment_type_id and practitioner_id:
                    try:
                        today_str = datetime.datetime.utcnow().strftime("%Y-%m-%d")
                        to_str = (datetime.datetime.utcnow() + datetime.timedelta(days=6)).strftime("%Y-%m-%d")
                        avail = api.connectors.invoke(
                            server="cliniko-scheduling", tool="get_available_times",
                            args={"business_id": business_id, "practitioner_id": practitioner_id, "appointment_type_id": appointment_type_id, "from_time": today_str, "to_time": to_str},
                        )
                        raw_slots = avail if isinstance(avail, list) else (avail or {}).get("available_times") or []
                        for s in raw_slots[:3]:
                            t = s.get("appointment_start") if isinstance(s, dict) else s
                            if t:
                                slot_options.append(str(t))
                    except Exception:
                        slot_options = []
                    if slot_options:
                        proposed_appointment = {
                            "appointment_type_id": appointment_type_id,
                            "business_id": business_id,
                            "practitioner_id": practitioner_id,
                            "starts_at": slot_options[0],
                        }

            enquirer_first = str(triage.get("enquirer_first_name") or "").strip()
            enquirer_last = str(triage.get("enquirer_last_name") or "").strip()
            enquirer_name = (enquirer_first + " " + enquirer_last).strip() or item.get("from_name") or item.get("from_email") or "there"

            try:
                ai_reply = api.ai.extract(
                    prompt=AI_REPLY_PROMPT,
                    input=json.dumps({
                        "enquirer_name": enquirer_name,
                        "reason_for_visit": triage.get("reason_for_visit") or "",
                        "tone": tone,
                        "services": services[:15],
                        "proposed_times": slot_options,
                        "appointment_type_name": appt_type_name,
                    }),
                    schema_hint=AI_REPLY_HINT,
                )
            except Exception:
                ai_reply = {}
            ai_reply = ai_reply if isinstance(ai_reply, dict) else {}
            reply_subject = ai_reply.get("subject") or ("Re: " + (item.get("subject") or "your enquiry"))
            reply_body = ai_reply.get("body") or (
                "Hi " + enquirer_name + ", thanks for getting in touch. We'll follow up shortly with times and pricing."
            )

            description = (
                "**From:** " + enquirer_name + " (" + (item.get("from_email") or "") + ")  \n"
                "**Practice:** " + (practice.get("name") or slug) + "  \n"
                "**Reason given:** " + (triage.get("reason_for_visit") or "not stated") + "  \n\n"
                "**Drafted subject:** " + reply_subject + "  \n\n"
                "**Drafted message:**\n\n" + reply_body
            )
            if not appt_type_name:
                description += "\n\n_No new-patient appointment type is set for this practice, so no specific time could be proposed - add one in the practice's settings to enable this._"
            elif not proposed_appointment:
                description += "\n\n_Couldn't find an open slot to propose automatically - the reply doesn't include a specific time._"

            workq_item = api.workq.create(
                title="New enquiry: " + enquirer_name,
                scope="org",
                description=description,
                priority="normal",
                assignee_ids=[reviewer] if reviewer else None,
                labels=["healthcare-practice-management", "new-enquiry"],
            )
            workq_id = workq_item["id"]
            api.workq.attach_form(todo_id=workq_id, form_id=params["approval_form"])

            write_json("PracticeManager/NoShowDrafts/" + workq_id + ".json", {
                "slug": slug,
                "appointment_id": "",
                "patient_id": "",
                "patient_name": enquirer_name,
                "email": item.get("from_email") or "",
                "subject": reply_subject,
                "body": reply_body,
            })
            write_json("PracticeManager/EnquiryThreads/" + workq_id + ".json", {
                "slug": slug,
                "enquirer_name": enquirer_name,
                "enquirer_email": item.get("from_email") or "",
                "reason_for_visit": triage.get("reason_for_visit") or "",
                "proposed_appointment": proposed_appointment,
                "intake_form_template_id": practice.get("intake_form_template_id") or "",
                "reviewer_id": reviewer,
                "drafted_at": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
                "status": "awaiting_reply",
                "patient_id": "",
                "appointment_id": "",
                "patient_form_id": "",
