import json
import datetime


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True))


now = datetime.datetime.utcnow()
cutoff = now - datetime.timedelta(days=30)

threads = []
try:
    entries = api.files.list(path="PracticeManager/EnquiryThreads", scope="org")
except Exception:
    entries = []
for entry in entries or []:
    fname = entry.get("name") if isinstance(entry, dict) else entry
    if not fname or not str(fname).endswith(".json"):
        continue
    todo_id = str(fname)[:-5]
    thread = read_json("PracticeManager/EnquiryThreads/" + fname, {}) or {}
    if not thread or not thread.get("enquirer_email"):
        continue
    # Only threads actively waiting on a reply are candidates - a booked/re-offered/not-booked/stale
    # thread must not be matched again (idempotency).
    if thread.get("status") != "awaiting_reply":
        continue
    drafted_at = str(thread.get("drafted_at") or "")
    try:
        drafted_dt = datetime.datetime.strptime(drafted_at, "%Y-%m-%dT%H:%M:%SZ") if drafted_at else now
    except ValueError:
        drafted_dt = now
    if drafted_dt < cutoff:
        continue
    threads.append({"todo_id": todo_id, "thread": thread})

if not threads:
    confirmed_reply_items = []
else:
    try:
        emails = api.connectors.invoke(server="m365-mail-read", tool="list_emails", args={"folder": "Inbox", "limit": 50, "unreadOnly": True})
    except Exception:
        emails = []
    if not isinstance(emails, list):
        emails = []

    seen = read_json("PracticeManager/EnquirySeen/replies_seen.json", default=[])
    if not isinstance(seen, list):
        seen = []
    seen_set = set(seen)

    by_email = {}
    for t in threads:
        key = str(t["thread"].get("enquirer_email") or "").lower()
        if key:
            by_email.setdefault(key, []).append(t)

    candidates = []
    newly_seen = set()
    for e in emails:
        if not isinstance(e, dict):
            continue
        email_id = e.get("id") or ""
        if not email_id or email_id in seen_set:
            continue
        sender = e.get("from") or {}
        from_email = str((sender.get("emailAddress") or {}).get("address") or "").lower()
        matches = by_email.get(from_email) or []
        if not matches:
            continue
        match = matches[-1]
        candidates.append({
            "email_id": email_id,
            "todo_id": match["todo_id"],
            "thread": match["thread"],
        })
        newly_seen.add(email_id)

    if newly_seen:
        seen_set |= newly_seen
        write_json("PracticeManager/EnquirySeen/replies_seen.json", sorted(seen_set))

    confirmed_reply_items = candidates
